import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useCallback, useMemo, useState } from 'react';
import { Alert, Platform, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, useColorScheme, View } from 'react-native';
import { PayrollNavigationList } from '../../../utils/types/index.type';
import { Colors } from '../../../utils/constants/Colors';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useAppContainer } from '../../../configuration/navigation/AppContainer';
import { Borders, Spacing, Typography } from '../../../utils/constants/Design';
import { ThemedView } from '../../../components/ui/ThemedView';
import { ThemedText } from '../../../components/ui/ThemedText';
import { IconSymbol } from '../../../components/ui/icon-symbol';
import { SocketIO } from '../../../configuration/helpers/main.helpers';
import { useFocusEffect } from '@react-navigation/native';
import { formatCurrency } from '../../../utils/constants/Currency';

type TPayAllowanceListScreen = NativeStackScreenProps<PayrollNavigationList, "AllowanceListScreen">

const PayAllowanceListScreen = ({navigation}: TPayAllowanceListScreen) => {
    const colorScheme = useColorScheme();
    const themeColors = Colors[colorScheme ?? 'light'];
    const isDark = colorScheme === 'dark';
    const insets = useSafeAreaInsets();
    const { session, selectedBusiness, can, businessCurrency } = useAppContainer();

    const [searchQuery, setSearchQuery] = useState('');
    const [isSearchVisible, setIsSearchVisible] = useState(false);
    const [data, setData] = useState<any[]>([]);

    const fetchAllowances = async () => {
        SocketIO.emit(
            'fetch-pay-allowances',
            {
                sessionID: session,
                businessID: selectedBusiness.id
            },
            (response:any) => {
                if (response.status === "success") {
                    setData(response.data || []);
                } else {
                    Alert.alert(
                        "Error",
                        response.message || "Error fetching allowances"
                    );
                }
            }
        );
    };

    useFocusEffect(
        useCallback(() => {
            fetchAllowances();
        }, [])
    );

    const filteredOptions = useMemo(() => {
        if (!searchQuery.trim()) return data;

        return data.filter(option =>
            String(option.name)
                .toLowerCase()
                .includes(searchQuery.toLowerCase())
        );
    }, [searchQuery, data]);

    const formatAmount = (item:any) => {
        if (item.type === 'percentage') {
            return `${item.amount}%`;
        }
        let amount = formatCurrency(Number(item.amount ?? 0), {symbol: businessCurrency.symbol})
        return String(amount);
    };

    const formatType = (item:any) => {
        return item.type === 'percentage'
            ? 'Percentage'
            : 'Fixed Amount';
    };

    const formatStage = (item:any) => {
        return item.stage === 'net'
            ? 'Net Salary'
            : 'Gross Salary';
    };

    return (
        <View style={[styles.container, {
            backgroundColor: themeColors.background
        }]}>
            {Platform.OS === 'android' && (
                <View style={[
                    styles.statusBarSpacer,
                    {
                        height: 10,
                        backgroundColor: themeColors.background
                    }
                ]} />
            )}

            <View style={[
                styles.safeArea,
                {
                    backgroundColor: themeColors.background,
                    paddingTop: Platform.OS === 'ios'
                        ? insets.top
                        : 0
                }
            ]}>
                <ThemedView style={[
                    styles.header,
                    {
                        backgroundColor: themeColors.background,
                        borderBottomColor: themeColors.border
                    }
                ]}>
                    {isSearchVisible ? (
                        <View style={styles.searchHeaderContainer}>
                            <TouchableOpacity
                                style={styles.backButton}
                                onPress={() => {
                                    setIsSearchVisible(false);
                                    setSearchQuery('');
                                }}
                            >
                                <IconSymbol
                                    name="arrow.left"
                                    size={22}
                                    color={themeColors.text}
                                />
                            </TouchableOpacity>

                            <View style={[
                                styles.searchInputContainer,
                                {
                                    backgroundColor: themeColors.inputBackground
                                }
                            ]}>
                                <IconSymbol
                                    name="magnifyingglass"
                                    size={18}
                                    color={themeColors.subtleText}
                                />

                                <TextInput
                                    style={[
                                        styles.searchInputField,
                                        {
                                            color: themeColors.text
                                        }
                                    ]}
                                    placeholder="Search allowances"
                                    placeholderTextColor={themeColors.subtleText}
                                    value={searchQuery}
                                    onChangeText={setSearchQuery}
                                    autoFocus
                                />
                            </View>
                        </View>
                    ) : (
                        <>
                            <TouchableOpacity
                                onPress={() => navigation.goBack()}
                                style={[
                                    styles.backButtonMain,
                                    {
                                        backgroundColor: themeColors.subtleBackground
                                    }
                                ]}
                            >
                                <IconSymbol
                                    name="arrow.left"
                                    size={20}
                                    color={themeColors.icon}
                                />
                            </TouchableOpacity>

                            <ThemedText style={styles.headerTitle}>
                                Allowances
                            </ThemedText>

                            <View style={styles.headerRight}>
                                <TouchableOpacity
                                    style={[
                                        styles.iconButton,
                                        {
                                            backgroundColor: isDark
                                                ? themeColors.card
                                                : themeColors.subtleBackground
                                        }
                                    ]}
                                    onPress={() => setIsSearchVisible(true)}
                                >
                                    <IconSymbol
                                        name="magnifyingglass"
                                        size={22}
                                        color={themeColors.icon}
                                    />
                                </TouchableOpacity>

                                {can("hrm.employee.create_update") && (
                                    <TouchableOpacity
                                        onPress={() => navigation.navigate(
                                            'AllowanceFormScreen',
                                            { data: null }
                                        )}
                                        style={[
                                            styles.iconButton,
                                            {
                                                backgroundColor: isDark
                                                    ? themeColors.card
                                                    : themeColors.subtleBackground
                                            }
                                        ]}
                                    >
                                        <IconSymbol
                                            name="plus"
                                            size={22}
                                            color={themeColors.icon}
                                        />
                                    </TouchableOpacity>
                                )}
                            </View>
                        </>
                    )}
                </ThemedView>

                <ScrollView
                    style={styles.content}
                    contentContainerStyle={[
                        styles.contentContainer,
                        {
                            paddingBottom: insets.bottom + Spacing.screenPadding
                        }
                    ]}
                    showsVerticalScrollIndicator={false}
                >
                    <View style={styles.tabContent}>
                        <View style={styles.accountsList}>
                            {filteredOptions.length > 0 ? (
                                filteredOptions.map((item, index) => (
                                    <TouchableOpacity
                                        key={index}
                                        style={[
                                            styles.accountCard,
                                            {
                                                backgroundColor: themeColors.card,
                                                borderLeftColor: themeColors.primary
                                            }
                                        ]}
                                        onPress={() => {}}
                                        activeOpacity={0.8}
                                    >
                                        <View style={styles.accountCardContent}>
                                            <View style={styles.accountTitleRow}>
                                                <View style={{
                                                    width: '67%'
                                                }}>
                                                    <Text
                                                        style={[
                                                            styles.accountName,
                                                            {
                                                                color: themeColors.text
                                                            }
                                                        ]}
                                                        numberOfLines={1}
                                                    >
                                                        {item.name || ''}
                                                    </Text>

                                                    <Text style={[
                                                        styles.accountType,
                                                        {
                                                            color: themeColors.subtleText
                                                        }
                                                    ]}>
                                                        {formatAmount(item)} · {formatType(item)}
                                                    </Text>

                                                    <View style={{
                                                        flexDirection: 'row',
                                                        marginTop: 5,
                                                        gap: 5,
                                                        flexWrap: 'wrap'
                                                    }}>
                                                        <View style={[
                                                            styles.badge,
                                                            {
                                                                backgroundColor: themeColors.border
                                                            }
                                                        ]}>
                                                            <Text style={[
                                                                styles.badgeText,
                                                                {
                                                                    color: themeColors.subtleText
                                                                }
                                                            ]}>
                                                                {formatStage(item)}
                                                            </Text>
                                                        </View>

                                                        {item.isAutomatic === 'yes' && (
                                                            <View style={[
                                                                styles.badge,
                                                                {
                                                                    backgroundColor: themeColors.primary
                                                                }
                                                            ]}>
                                                                <Text style={[
                                                                    styles.badgeText,
                                                                    {
                                                                        color: themeColors.white
                                                                    }
                                                                ]}>
                                                                    Automatic
                                                                </Text>
                                                            </View>
                                                        )}
                                                    </View>
                                                </View>

                                                <View style={{
                                                    flexDirection: 'row',
                                                    width: '30%',
                                                    justifyContent: 'flex-end'
                                                }}>
                                                    {can("hrm.employee.create_update") && (
                                                        <TouchableOpacity
                                                            onPress={() => navigation.navigate(
                                                                'AllowanceFormScreen',
                                                                { data: item }
                                                            )}
                                                            style={[
                                                                styles.iconButton,
                                                                {
                                                                    backgroundColor: themeColors.tabIconDefault
                                                                }
                                                            ]}
                                                        >
                                                            <IconSymbol
                                                                name="pencil"
                                                                size={18}
                                                                color={themeColors.white}
                                                            />
                                                        </TouchableOpacity>
                                                    )}
                                                </View>
                                            </View>

                                            {item.description ? (
                                                <Text
                                                    style={[
                                                        styles.description,
                                                        {
                                                            color: themeColors.subtleText
                                                        }
                                                    ]}
                                                    numberOfLines={2}
                                                >
                                                    {item.description}
                                                </Text>
                                            ) : null}
                                        </View>
                                    </TouchableOpacity>
                                ))
                            ) : (
                                <ThemedText style={{
                                    textAlign: 'center',
                                    color: themeColors.subtleText,
                                    marginTop: 50
                                }}>
                                    No allowances found
                                </ThemedText>
                            )}
                        </View>
                    </View>
                </ScrollView>
            </View>
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
    },
    statusBarSpacer: {
        width: '100%',
    },
    safeArea: {
        flex: 1,
    },
    header: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingHorizontal: Spacing.screenPadding,
        paddingVertical: Spacing.medium,
        borderBottomWidth: 1,
    },
    backButtonMain: {
        width: 36,
        height: 36,
        borderRadius: 18,
        alignItems: 'center',
        justifyContent: 'center',
    },
    headerTitle: {
        fontSize: Typography.heading2,
        fontFamily: 'SemiBold'
    },
    headerRight: {
        flexDirection: 'row',
        alignItems: 'center',
        flexShrink: 0,
    },
    iconButton: {
        width: 40,
        height: 40,
        borderRadius: 20,
        alignItems: 'center',
        justifyContent: 'center',
        marginLeft: Spacing.small,
    },
    content: {
        flex: 1,
    },
    contentContainer: {
        padding: Spacing.small,
    },
    searchHeaderContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        width: '100%',
        paddingHorizontal: 0,
    },
    backButton: {
        alignItems: 'center',
        justifyContent: 'center',
        marginRight: Spacing.medium,
        width: 40,
        height: 40,
        flexShrink: 0,
    },
    searchInputContainer: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
        paddingHorizontal: Spacing.medium,
        borderRadius: Borders.radiusMedium,
    },
    searchInputField: {
        flex: 1,
        fontSize: Typography.body,
        marginLeft: Spacing.small,
        fontFamily: 'Regular',
        paddingVertical: 12
    },
    tabContent: {
        flex: 1,
    },
    accountsList: {
        gap: 3,
    },
    accountCard: {
        borderRadius: 2,
        overflow: 'hidden',
        borderBottomWidth: 0.09,
        borderLeftWidth: 3
    },
    accountCardContent: {
        padding: Spacing.large,
        position: 'relative',
    },
    accountTitleRow: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: 4,
    },
    accountName: {
        fontSize: 11,
        fontFamily: 'SemiBold',
        marginBottom: 5
    },
    accountType: {
        fontFamily: 'Regular',
        fontSize: Typography.small,
    },
    description: {
        fontFamily: 'Regular',
        fontSize: Typography.small,
        marginTop: 8,
        lineHeight: 17
    },
    badge: {
        paddingHorizontal: 7,
        paddingVertical: 3,
        borderRadius: Borders.radiusSmall,
    },
    badgeText: {
        fontSize: 9,
        fontFamily: 'SemiBold'
    },
});

export default PayAllowanceListScreen;